/**
 * Cloudflare Workers build patch (prebuild:cf).
 *
 * Why: `@napi-rs/canvas/js-binding.js` (auto-generated by NAPI-RS) statically
 * requires the platform binary packages, e.g. `require('@napi-rs/canvas-linux-x64-gnu')`
 * whose package main is a `.node` native binary. The OpenNext Cloudflare bundler
 * (esbuild) has no loader for `.node` files, so any statically-resolvable native
 * require fails the bundling step with:
 *   "No loader is configured for `.node` files".
 *
 * esbuild treats requires that (a) it cannot statically resolve AND (b) are
 * wrapped in try/catch as optional (warning only). So we rewrite the two linux
 * package specifiers into a computed (non-analyzable) form, e.g.:
 *   require(['@napi-rs/canvas-linux-x64', 'gnu'].join('-'))
 * which resolves to exactly the same package at run-time on Node, while letting
 * the Cloudflare bundle pass (the binaries stay inert files in the output; the
 * canvas feature degrades at run-time on Workers, which is documented).
 *
 * Idempotent + fail-open: never breaks the build if the file moves/changes.
 */
const fs = require('fs');
const path = require('path');

function main() {
  const candidates = [
    path.join(process.cwd(), 'node_modules', '@napi-rs', 'canvas', 'js-binding.js'),
  ];
  const file = candidates.find((p) => fs.existsSync(p));
  if (!file) {
    console.log('[patch-canvas-cf] @napi-rs/canvas not found, skipping.');
    return;
  }
  let src = fs.readFileSync(file, 'utf8');
  if (src.includes("].join('-')")) {
    console.log('[patch-canvas-cf] already patched, skipping.');
    return;
  }
  const before = src;
  // Keep run-time behavior identical on Node; only hide the specifier from esbuild.
  src = src.replaceAll(
    "require('@napi-rs/canvas-linux-x64-musl')",
    "require(['@napi-rs/canvas-linux-x64', 'musl'].join('-'))",
  );
  src = src.replaceAll(
    "require('@napi-rs/canvas-linux-x64-gnu')",
    "require(['@napi-rs/canvas-linux-x64', 'gnu'].join('-'))",
  );
  if (src === before) {
    console.log('[patch-canvas-cf] nothing to patch (unexpected file contents), skipping.');
    return;
  }
  fs.writeFileSync(file, src);
  console.log('[patch-canvas-cf] patched js-binding.js linux requires for Cloudflare bundling.');
}

try {
  main();
} catch (e) {
  console.log('[patch-canvas-cf] patch failed (ignored): ' + (e && e.message));
}
